    ffi.NativeFunction<
      ffi.Int Function(
        ffi.Pointer<ffi.Uint8> ciphertext,
        ffi.Pointer<ffi.Uint8> shared_secret,
        ffi.Pointer<ffi.Uint8> public_key,
        ffi.Pointer<ffi.Uint8> seed,
